import re

def compare_one(a, b):
	"""
	Create a function that takes integers, floats, or strings representing
	real numbers, and returns the larger variable in its given variable type.
	Return None if the values are equal.
	Note: If a real number is represented as a string, the floating point might be . or ,
	"""

	# Try to convert inputs to float
	try:
		a_float = float(a)
		b_float = float(b)

		# If both conversions are successful, return the larger float
		if a_float > b_float:
			return a_float
		elif a_float < b_float:
			return b_float
		else:
			return None
	except ValueError:
		# If either conversion fails, try to extract the number from the string
		try:
			a_num = re.search(r'\d+(?:\.\d+)?', a).group()
			b_num = re.search(r'\d+(?:\.\d+)?', b).group()

			# Convert extracted numbers to float and return the larger
			a_float = float(a_num)
			b_float = float(b_num)
			if a_float > b_float:
				return a
			elif a_float < b_float:
				return b
			else:
				return None
		except AttributeError:
			# If no number is found in either string, return the larger string
			if a > b:
				return a
			elif a < b:
				return b
			else:
				return None
