import math

def is_multiply_prime(a):
    """
    Returns true if the given number is the multiplication of 3 prime numbers and false otherwise.
    """

    # Define a helper function to check if a number is prime
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    # Find all prime numbers less than or equal to a
    primes = [i for i in range(2, a + 1) if is_prime(i)]

    # Check if a can be expressed as the product of 3 prime numbers
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            for k in range(j + 1, len(primes)):
                if a == primes[i] * primes[j] * primes[k]:
                    return True

    return False
