        return 1
    return (modpow(n, p - 2, p) * (fact_modp(n, p) // fact_modp(r, p) // fact_modp(n - r, p))) % p

def fact_modp(n, p):
    res = 1
    for i in range(1, n + 1):
        res = (res * i) % p
    return res
