    parentheses_map = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in parentheses_map.values():
            stack.append(char)
        elif char in parentheses_map.keys():
            if stack == [] or stack.pop() != parentheses_map[char]:
                return False
    return stack == []
