def get_maxgold(gold, rows, cols):
    dp = [[0]*cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                dp[i][j] = gold[i][j]
            elif i == 0:
                dp[i][j] = gold[i][j] + dp[i][j-1]
            elif j == 0:
                dp[i][j] = gold[i][j] + dp[i-1][j]
            else:
                dp[i][j] = gold[i][j] + max(dp[i-1][j], dp[i][j-1])

    return max(dp[-1])
```

