def max_path_sum(triangle, row, col):
    def helper(triangle, row, col, memo):
        if row == len(triangle) - 1:
            return triangle[row][col]
        if (row, col) in memo:
            return memo[(row, col)]
        memo[(row, col)] = triangle[row][col] + max(helper(triangle, row + 1, col, memo), helper(triangle, row + 1, col + 1, memo))
        return memo[(row, col)]

    return helper(triangle, 0, 0, {})
