def zigzag(n, k):
    """
    Calculate the Entringer number e(n, k).

    Parameters:
    n (int): The number of elements.
    k (int): The number of elements to choose.

    Returns:
    int: The Entringer number e(n, k).
    """
    if k == 0 or k == n:
        return 1
    else:
        return sum((-1)**(k-j)*math.comb(n-1, k-j)*math.comb(n-k, j) 
                   for j in range(k+1))
