    def helper(i, j, total):
        if i == n:
            return 1 if j == n else 0
        if (i, j, total) in memo:
            return memo[(i, j, total)]
        count = 0
        for k in range(i, n):
            if int(s[k]) + total <= j - k:
                count += helper(k + 1, j, total + int(s[k]))
        memo[(i, j, total)] = count
        return count

    memo = {}
    return helper(0, n, 0)
```

