def magic_square_test(square):
    n = len(square)
    target_sum = sum(square[0])
    if target_sum % n != 0:
        return False
    target_row_sum = target_sum // n
    target_col_sum = target_row_sum
    target_diagonal_sum = target_row_sum * 2
    for i in range(n):
        row_sum = sum(square[i])
        col_sum = sum(square[j][i] for j in range(n))
        if row_sum != target_row_sum or col_sum != target_col_sum:
            return False
        if i == n - i - 1:
            diagonal_sum = sum(square[i][i] for i in range(n))
            if diagonal_sum != target_diagonal_sum:
                return False
    return True
