        for j in range(1, target + 1):
            if arr[i - 1] == j:
                dp[i][j] = 1
            elif abs(arr[i - 1] - j) <= 1 and i > 1:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - abs(arr[i - 1] - j)] + 1)
