import re

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Try to split on whitespace
    try:
        return re.split(r'\s+', txt)
    except ValueError:
        # If no whitespace, try to split on comma
        try:
            return re.split(r',', txt)
        except ValueError:
            # If no comma, count the number of lower-case letters with odd order in the alphabet
            return sum(1 for i, c in enumerate(txt) if c.islower() and (ord(c) - ord('a')) % 2 == 1)
