def ncr_modp(n, r, p):
    def modpow(x, y, p):
        res = 1
        while y > 0:
            if y & 1:
                res = (res * x) % p
            x = (x * x) % p
            y >>= 1
        return res

    if r > n:
        return 0
    if r == 0 or n == r:
        return 1
    numerator = 1
    denominator = 1
    for i in range(r):
        numerator = (numerator * (n - i)) % p
        denominator = (denominator * (i + 1)) % p
    result = (modpow(denominator, p - 2, p) * numerator) % p
    return result
```

