    for i in range(start, end + 1):
        found = False
        for r in ranges:
            if r[0] <= i <= r[1]:
                found = True
                break
        if not found:
            missing_ranges.append((i, end))
    for r in ranges:
        for i in range(r[0] + 1, r[1]):
            found = False
            for r2 in ranges:
                if r2[0] <= i <= r2[1]:
