def ncr_modp(n, r, p):
    def modpow(x, y, p):
        res = 1
        x = x % p
        if x == 0:
            return 0
        while y > 0:
            if y & 1:
                res = (res * x) % p
            y = y >> 1
            x = (x * x) % p
        return res

    if r > n:
        return 0
    if r == 0 or n == r:
        return 1
    return (modpow(n, p - 2, p) * modpow(r, p - 2, p) * modpow(n - r, p - 2, p)) % p
