import re

def compare_one(a, b):
    """
    Create  a  function  that  takes  integers,  floats,  or  strings  representing
    real  numbers,  and  returns  the  larger  variable  in  its  given  variable  type.
    Return  None  if  the  values  are  equal.
    Note:  If  a  real  number  is  represented  as  a  string,  the  floating  point  might  be  . or  ,

    compare_one(1,  2.5)  ➞  2.5
    compare_one(1,  "2,3")  ➞  "2,3"
    compare_one("5,1",  "6")  ➞  "6"
    compare_one("1",  1)  ➞  None
    """

    # Try to convert inputs to float
    try:
        a_float = float(a)
        b_float = float(b)

        # If both are floats, return the larger one
        if isinstance(a_float, float) and isinstance(b_float, float):
            return max(a_float, b_float)

        # If one is a float and the other is not, return the float
        elif isinstance(a_float, float):
            return a_float
        elif isinstance(b_float, float):
            return b_float

    # If inputs cannot be converted to float, try to extract the number from the string
    except ValueError:
        # Use regular expression to extract the number from the string
        a_num = re.search(r"[-+]?\d*\.\d+|[-+]?\d+", str(a))
        b_num = re.search(r"[-+]?\d*\.\d+|[-+]?\d+", str(b))

        # If both are numbers, return the larger one
        if a_num and b_num:
            a_num = float(a_num.group())
            b_num = float(b_num.group())
            return max(a_num, b_num)

        # If one is a number and the other is not, return the number
        elif a_num:
            return float(a_num.group())
        elif b_num:
            return float(b_num.group())

    # If inputs are not numbers, return None
    return None
