    for i in range(1, n + 1):
        dp[i][0] = 1
        for j in range(1, i + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]
            if arr[i - 1] > k:
                dp[i][j] = dp[i - 1][j]
            elif arr[i - 1] > 1:
                dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1] - dp[i - 1][j - 1]
