    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    max_sum_inc = [0]*n
    max_sum_dec = [0]*n

    max_sum_inc[0] = arr[0]
    max_sum_dec[n-1] = arr[n-1]

    for i in range(1, n):
        max_sum_inc[i] = max(max_sum_inc[i-1], arr[i])

    for i in range(n-2, -1, -1):
        max_sum_dec[i] = max(max_sum_dec[i+1], arr[i])

