            return b, 0, 1
        else:
            gcd, x, y = extended_gcd(b % a, a)
            return gcd, y - (b // a) * x, x

    def mod_inverse(a, m):
        gcd, x, y = extended_gcd(a, m)
        if gcd != 1:
            return None
        else:
            return x % m

    count = 0
    for num in arr:
        if num % p == 1:
            count += 1
        elif mod_inverse(num, n) is not None:
            count += 1
    return count
