import heapq

def find_minimum_range(arrays):
    min_heap = []
    for i, array in enumerate(arrays):
        if array:
            heapq.heappush(min_heap, (array[0], i, 0))

    min_range = float('inf')
    current_min = float('inf')
    while min_heap:
        val, array_index, element_index = heapq.heappop(min_heap)
        if element_index + 1 < len(arrays[array_index]):
            heapq.heappush(min_heap, (arrays[array_index][element_index + 1], array_index, element_index + 1))
        current_min = val
        for i, array in enumerate(arrays):
            if array and array[0] < current_min:
                heapq.heappush(min_heap, (array[0], i, 0))
        if len(min_heap) == len(arrays):
            min_range = min(min_range, current_min + arrays[array_index][element_index + 1] - current_min)

    return (min_range - current_min, min_range)
