def max_fill(grid, capacity):
    import math
    def get_water(well):
        return sum(grid[i][j] for i in range(len(grid)) for j in range(len(grid[0])) if i == well)

    def fill_bucket(well, bucket):
        return min(bucket, get_water(well))

    def empty_bucket(well, bucket):
        return bucket - fill_bucket(well, bucket)

    def fill_bucket_from_bucket(well, bucket, bucket_from):
        return min(bucket, empty_bucket(well, bucket_from))

    def empty_bucket_from_bucket(well, bucket, bucket_from):
        return bucket_from - fill_bucket_from_bucket(well, bucket, bucket_from)

    def get_max_fill(well, bucket, bucket_from):
        if get_water(well) == 0:
            return 0
        if bucket == 0:
            return 1 + get_max_fill(well, capacity, bucket_from)
        if bucket_from == 0:
            return 1 + get_max_fill(well, bucket - fill_bucket(well, bucket), bucket)
        return 1 + get_max_fill(well, fill_bucket_from_bucket(well, bucket, bucket_from), empty_bucket_from_bucket(well, bucket, bucket_from))

    max_fill_count = 0
    for well in range(len(grid)):
        max_fill_count += get_max_fill(well, capacity, capacity)

    return max_fill_count
```

