def count_pairs(arr, k, n):
    arr.sort()
    count = 0
    left = 0
    right = 1
    while right < n:
        if arr[right] - arr[left] == k:
            count += 1
            right += 1
            while right < n and arr[right] - arr[left] == k:
                right += 1
            left = right - 1
        elif arr[right] - arr[left] < k:
            right += 1
        else:
            left += 1
    return count
