        for j in range(cols):
            if i == 0 and j == 0:
                dp[i][j] = gold[i][j]
            elif i == 0:
                dp[i][j] = gold[i][j] + dp[i][j-1]
            elif j == 0:
                dp[i][j] = gold[i][j] + dp[i-1][j]
