def solution(a, b, n):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            gcd, x, y = extended_gcd(b % a, a)
            return gcd, y - (b // a) * x, x

    gcd, x, y = extended_gcd(a, b)
    if n % gcd != 0:
        return 'No solution'
    else:
        x *= n // gcd
        y *= n // gcd
        return ('x = ', x, ', y = ', y)
