def max_fill(grid, capacity):
    import math
    def get_water(well):
        return sum(grid[i][j] for i in range(len(grid)) for j in range(len(grid[0])) if i == well)

    def fill_bucket(well, bucket):
        return min(bucket, get_water(well))

    def empty_bucket(well, bucket):
        return bucket - fill_bucket(well, bucket)

    def fill_bucket_from(well, bucket, prev_bucket):
        return max(0, fill_bucket(well, bucket) - empty_bucket(well, prev_bucket))

    def empty_bucket_from(well, bucket, prev_bucket):
        return max(0, empty_bucket(well, bucket) - fill_bucket(well, prev_bucket))

    def get_max_fill(well, bucket, prev_bucket):
        if get_water(well) == 0:
            return 0
        return 1 + get_max_fill(well + 1, fill_bucket_from(well, bucket, prev_bucket), empty_bucket_from(well, bucket, prev_bucket))

    return get_max_fill(0, capacity, 0)
```

