def ncr_modp(n, r, p):
    if r > n - r:
        r = n - r

    def factorial_mod(x, p):
        result = 1
        for i in range(1, x + 1):
            result = (result * i) % p
        return result

    numerator = factorial_mod(n, p)
    denominator = factorial_mod(r, p) * factorial_mod(n - r, p)
    return (numerator * pow(denominator, p - 2, p)) % p
```

