def group_tuples(tuples_list):
    first_elements = {}
    for tup in tuples_list:
        first_element = tup[0]
        if first_element in first_elements:
            first_elements[first_element].append(tup[1])
        else:
            first_elements[first_element] = [tup[1]]

    result = []
    for key in first_elements:
        result.append((key, *first_elements[key]))

    return result
